<div class="d-flex justify-content-between align-items-center mb-3"><div><h4 class="fw-bold mb-1">Data <?= esc($config['title']) ?></h4><div class="muted">Pencarian dan pengelolaan data master.</div></div><a class="btn btn-primary" href="<?= site_url('admin/'.$resource.'/new') ?>">+ Tambah Data</a></div><div class="panel"><form class="row g-2 mb-3"><div class="col-md-5"><input class="form-control" name="q" value="<?= esc($q) ?>" placeholder="Cari nama, nomor induk, atau kode"></div><div class="col-auto"><button class="btn btn-outline-primary">Cari</button><a class="btn btn-light" href="<?= site_url('admin/'.$resource) ?>">Reset</a></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><?php if($resource==='mahasiswa'): ?><th>Foto</th><th>NIM</th><th>Nama</th><th>Angkatan</th><th>Dosen Wali</th><?php elseif($resource==='dosen'): ?><th>NIDN</th><th>Nama</th><th>Email</th><?php else: ?><th>Kode</th><th>Mata Kuliah</th><th>SKS</th><th>Semester</th><th>Dosen</th><th>Kuota</th><?php endif ?><th class="text-end">Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php if($resource==='mahasiswa'): ?><td><?php if($r['foto']): ?><img class="avatar" src="<?= base_url('uploads/foto/'.$r['foto']) ?>"><?php else: ?><span class="avatar bg-light d-inline-flex align-items-center justify-content-center">👤</span><?php endif ?></td><td><?= esc($r['nim']) ?></td><td><?= esc($r['nama']) ?></td><td><?= esc($r['angkatan']) ?></td><td><?= esc($r['nama_wali']??'-') ?></td><?php elseif($resource==='dosen'): ?><td><?= esc($r['nidn']) ?></td><td><?= esc($r['nama']) ?></td><td><?= esc($r['email']??'-') ?></td><?php else: ?><td><?= esc($r['kode']) ?></td><td><?= esc($r['nama']) ?></td><td><?= esc($r['sks']) ?></td><td><?= esc($r['semester']) ?></td><td><?= esc($r['nama_dosen']??'-') ?></td><td><?= esc($r['kuota']) ?></td><?php endif ?><td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('admin/'.$resource.'/'.$r['id'].'/edit') ?>">Edit</a><form class="d-inline" method="post" action="<?= site_url('admin/'.$resource.'/'.$r['id'].'/delete') ?>" onsubmit="return confirm('Yakin menghapus data ini?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Hapus</button></form><?php if($resource!=='matakuliah'): ?><form class="d-inline" method="post" action="<?= site_url('admin/akun/'.$resource.'/'.$r['id'].'/reset') ?>" onsubmit="return confirm('Reset password ke NIM/NIDN?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-secondary">Reset Akun</button></form><?php endif ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="8" class="text-center muted py-4">Data tidak ditemukan.</td></tr><?php endif ?></tbody></table></div><div class="d-flex justify-content-between align-items-center"><small class="muted">Halaman <?= $pageNo ?> · Total data <?= $total ?></small><div><?php if($pageNo>1): ?><a class="btn btn-sm btn-outline-secondary" href="?q=<?= urlencode($q) ?>&page=<?= $pageNo-1 ?>">Sebelumnya</a><?php endif ?><?php if(count($rows)===10): ?><a class="btn btn-sm btn-outline-secondary" href="?q=<?= urlencode($q) ?>&page=<?= $pageNo+1 ?>">Berikutnya</a><?php endif ?></div></div></div>